-- Touchline — 0013: "Matchday week" (phase 2): training plans, match plans + marking, press conferences,
-- events inbox (Gabinete). Additive and drop-free. Content (questions, events, choices + effects) is generated by the
-- server and stored here; user commands only pick among stored options, and effects are applied by one bounded
-- SQL routine so a client can never invent an effect.

-- ------------------------------------------------------------------ tables
create table if not exists public.training_plans (
  club_id    uuid primary key references public.game_clubs(id) on delete cascade,
  game_id    uuid not null references public.games(id) on delete cascade,
  intensity  text not null default 'normal' check (intensity in ('light','normal','intense')),
  focus      text not null default 'none' check (focus in ('none','attack','defense','possession','set_pieces','fitness','tactics')),
  updated_at timestamptz not null default now()
);

create table if not exists public.match_plans (
  club_id    uuid primary key references public.game_clubs(id) on delete cascade,
  game_id    uuid not null references public.games(id) on delete cascade,
  rules      jsonb not null default '[]'::jsonb,
  marking    jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.press_conferences (
  id          uuid primary key default gen_random_uuid(),
  game_id     uuid not null references public.games(id) on delete cascade,
  club_id     uuid not null references public.game_clubs(id) on delete cascade,
  season      integer not null,
  round       integer not null,
  fixture_id  uuid references public.fixtures(id) on delete set null,
  opponent_club_id uuid references public.game_clubs(id) on delete set null,
  questions   jsonb not null,
  answers     jsonb,
  effects     jsonb,
  answered_at timestamptz,
  created_at  timestamptz not null default now(),
  unique (club_id, season, round)
);
create index if not exists press_game_idx on public.press_conferences(game_id, season, round);

create table if not exists public.inbox_events (
  id             uuid primary key default gen_random_uuid(),
  game_id        uuid not null references public.games(id) on delete cascade,
  club_id        uuid not null references public.game_clubs(id) on delete cascade,
  season         integer not null,
  round          integer not null,
  key            text not null,
  title          text not null,
  body           text not null,
  payload        jsonb not null default '{}'::jsonb,
  choices        jsonb not null,
  default_choice integer not null default 0,
  deadline_round integer not null,
  chosen         integer,
  resolution     text check (resolution in ('answered','default')),
  resolved_at    timestamptz,
  created_at     timestamptz not null default now(),
  unique (club_id, season, round, key)
);
create index if not exists inbox_club_idx on public.inbox_events(club_id, resolved_at);

do $$
declare t text;
begin
  foreach t in array array['training_plans','match_plans','press_conferences','inbox_events'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;
-- plans and the inbox are private to the club; press answers are public to the league once given (they are quotes)
create policy own_club_read on public.training_plans for select to authenticated using (public.manages_club(club_id));
create policy own_club_read on public.match_plans for select to authenticated using (public.manages_club(club_id));
create policy own_club_read on public.inbox_events for select to authenticated using (public.manages_club(club_id));
create policy press_read on public.press_conferences for select to authenticated
  using (public.manages_club(club_id) or (answered_at is not null and public.is_game_member(game_id)));

-- ------------------------------------------------------------------ training
create or replace function public.save_training_plan(p_game_id uuid, p_intensity text, p_focus text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public.my_club_id(p_game_id); v_game public.games;
begin
  if v_club is null then perform public._fail('no_club', 'Não geres nenhum clube nesta liga.'); end if;
  select * into v_game from public.games where id = p_game_id;
  if public._game_is_processing(v_game) then perform public._fail('processing', 'Jornada em processamento.'); end if;
  if p_intensity not in ('light','normal','intense') or p_focus not in ('none','attack','defense','possession','set_pieces','fitness','tactics') then
    perform public._fail('invalid', 'Plano de treino inválido.');
  end if;
  insert into public.training_plans (club_id, game_id, intensity, focus) values (v_club, p_game_id, p_intensity, p_focus)
  on conflict (club_id) do update set intensity = excluded.intensity, focus = excluded.focus, updated_at = now();
end $$;

-- ------------------------------------------------------------------ match plan + marking
create or replace function public.save_match_plan(p_game_id uuid, p_rules jsonb, p_marking jsonb) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public.my_club_id(p_game_id); v_game public.games; r jsonb; v_id text;
begin
  if v_club is null then perform public._fail('no_club', 'Não geres nenhum clube nesta liga.'); end if;
  select * into v_game from public.games where id = p_game_id;
  if public._game_is_processing(v_game) then perform public._fail('processing', 'Jornada em processamento.'); end if;
  if jsonb_typeof(p_rules) <> 'array' or jsonb_array_length(p_rules) > 3 or jsonb_typeof(p_marking) <> 'array' or jsonb_array_length(p_marking) > 2 then
    perform public._fail('invalid', 'Máximo de 3 regras e 2 marcações.');
  end if;
  for r in select * from jsonb_array_elements(p_rules) loop
    if jsonb_typeof(r) <> 'object'
       or (r->>'minute') !~ '^\d+$' or (r->>'minute')::int not between 46 and 88
       or coalesce(r->>'when','') not in ('losing','drawing','winning')
       or (r ? 'mentality' and r->>'mentality' not in ('defensive','balanced','attacking'))
       or (not r ? 'mentality' and not r ? 'sub') then
      perform public._fail('invalid', 'Regra do plano de jogo inválida.');
    end if;
    if r ? 'sub' then
      if not exists (select 1 from public.game_players where id = (r#>>'{sub,out}')::uuid and club_id = v_club)
         or not exists (select 1 from public.game_players where id = (r#>>'{sub,in}')::uuid and club_id = v_club)
         or r#>>'{sub,out}' = r#>>'{sub,in}' then
        perform public._fail('invalid', 'Substituição do plano inválida.');
      end if;
    end if;
  end loop;
  for v_id in select jsonb_array_elements_text(p_marking) loop
    if not exists (select 1 from public.game_players p where p.id = v_id::uuid and p.game_id = p_game_id and p.club_id is distinct from v_club) then
      perform public._fail('invalid', 'Só podes marcar jogadores adversários desta liga.');
    end if;
  end loop;
  insert into public.match_plans (club_id, game_id, rules, marking) values (v_club, p_game_id, p_rules, p_marking)
  on conflict (club_id) do update set rules = excluded.rules, marking = excluded.marking, updated_at = now();
end $$;

-- ------------------------------------------------------------------ effects (internal, bounded)
-- effects: [{type:'morale', player_id?|scope:'squad', delta}, {type:'fitness'|'form', player_id, delta},
--           {type:'cash', delta_cents, reason}, {type:'injury'|'unavailable', player_id, matches}]
create or replace function public._apply_effects(p_game_id uuid, p_club_id uuid, p_effects jsonb, p_key text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare e jsonb; v_game public.games; v_pid uuid; v_d numeric;
begin
  select * into v_game from public.games where id = p_game_id;
  if p_effects is null or jsonb_typeof(p_effects) <> 'array' then return; end if;
  for e in select * from jsonb_array_elements(p_effects) loop
    v_pid := nullif(e->>'player_id', '')::uuid;
    if v_pid is not null and not exists (select 1 from public.game_players where id = v_pid and club_id = p_club_id) then
      continue; -- player left the club since the event was created
    end if;
    v_d := coalesce((e->>'delta')::numeric, 0);
    case e->>'type'
      when 'morale' then
        update public.game_players set morale = greatest(0, least(100, morale + greatest(-20, least(20, v_d))::int)), version = version + 1, updated_at = now()
         where club_id = p_club_id and (v_pid is null and e->>'scope' = 'squad' or id = v_pid);
      when 'fitness' then
        update public.game_players set fitness = greatest(0, least(100, fitness + greatest(-30, least(30, v_d))::int)), version = version + 1, updated_at = now()
         where id = v_pid;
      when 'form' then
        update public.game_players set form = greatest(-3, least(3, form + greatest(-1.5, least(1.5, v_d)))), version = version + 1, updated_at = now()
         where id = v_pid;
      when 'injury' then
        update public.game_players set injured_matches = greatest(injured_matches, greatest(0, least(6, (e->>'matches')::int))),
               injury_type = coalesce(injury_type, 'Lesão'), version = version + 1, updated_at = now() where id = v_pid;
      when 'unavailable' then
        update public.game_players set suspension_matches = greatest(suspension_matches, greatest(0, least(3, (e->>'matches')::int))),
               version = version + 1, updated_at = now() where id = v_pid;
      when 'cash' then
        if abs(coalesce((e->>'delta_cents')::bigint, 0)) between 1 and 1000000000 then
          perform public._ledger(p_game_id, p_club_id, 'adjustment', (e->>'delta_cents')::bigint, p_key,
                                 p_key || ':cash', v_game.current_season, v_game.current_matchday);
        end if;
      else null;
    end case;
  end loop;
end $$;

-- ------------------------------------------------------------------ inbox
create or replace function public.answer_inbox_event(p_event_id uuid, p_choice integer) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_e public.inbox_events; v_game public.games;
begin
  select * into v_e from public.inbox_events where id = p_event_id for update;
  if not found or not public.manages_club(v_e.club_id) then perform public._fail('not_found', 'Evento inexistente.'); end if;
  if v_e.resolved_at is not null then return jsonb_build_object('status', 'already', 'chosen', v_e.chosen); end if;
  select * into v_game from public.games where id = v_e.game_id;
  if public._game_is_processing(v_game) then perform public._fail('processing', 'Jornada em processamento.'); end if;
  if p_choice is null or p_choice < 0 or p_choice >= jsonb_array_length(v_e.choices) then perform public._fail('invalid', 'Escolha inválida.'); end if;
  perform public._apply_effects(v_e.game_id, v_e.club_id, v_e.choices->p_choice->'effects', 'event:' || v_e.id);
  update public.inbox_events set chosen = p_choice, resolution = 'answered', resolved_at = now() where id = v_e.id;
  perform public._audit(v_e.game_id, auth.uid(), 'inbox.answer', 'inbox_event', v_e.id::text, jsonb_build_object('choice', p_choice, 'key', v_e.key));
  return jsonb_build_object('status', 'answered', 'chosen', p_choice);
end $$;

-- server: apply the default choice of every expired event of a game (called before a matchday is simulated)
create or replace function public.resolve_due_events(p_game_id uuid, p_round integer) returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_e public.inbox_events; n integer := 0;
begin
  for v_e in select * from public.inbox_events where game_id = p_game_id and resolved_at is null and deadline_round <= p_round for update loop
    perform public._apply_effects(v_e.game_id, v_e.club_id, v_e.choices->v_e.default_choice->'effects', 'event:' || v_e.id);
    update public.inbox_events set chosen = v_e.default_choice, resolution = 'default', resolved_at = now() where id = v_e.id;
    n := n + 1;
  end loop;
  return n;
end $$;

-- ------------------------------------------------------------------ press conference
-- tones: confident / calm / provocative / evasive. Effects are fixed by the rules below (docs/game-design.md).
create or replace function public.answer_press(p_conf_id uuid, p_answers jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_c public.press_conferences; v_game public.games; a jsonb; q jsonb; v_tones text[] := '{}'; v_morale int := 0;
        v_own numeric := 0; v_opp numeric := 0; v_opp_human boolean; v_effects jsonb;
begin
  select * into v_c from public.press_conferences where id = p_conf_id for update;
  if not found or not public.manages_club(v_c.club_id) then perform public._fail('not_found', 'Conferência inexistente.'); end if;
  if v_c.answered_at is not null then perform public._fail('already', 'Já respondeste a esta conferência.'); end if;
  select * into v_game from public.games where id = v_c.game_id;
  if public._game_is_processing(v_game) then perform public._fail('processing', 'Jornada em processamento.'); end if;
  if v_c.season <> v_game.current_season or v_c.round <> v_game.current_matchday + 1 then
    perform public._fail('expired', 'Esta conferência já passou.');
  end if;
  if jsonb_typeof(p_answers) <> 'array' or jsonb_array_length(p_answers) <> jsonb_array_length(v_c.questions) then
    perform public._fail('invalid', 'Responde a todas as perguntas.');
  end if;
  for a in select * from jsonb_array_elements(p_answers) loop
    if coalesce(a->>'tone','') not in ('confident','calm','provocative','evasive')
       or char_length(coalesce(a->>'text','')) > 280
       or not exists (select 1 from jsonb_array_elements(v_c.questions) x where x->>'key' = a->>'key') then
      perform public._fail('invalid', 'Resposta inválida (máx. 280 caracteres).');
    end if;
    v_tones := v_tones || (a->>'tone');
  end loop;
  select manager_user_id is not null into v_opp_human from public.game_clubs where id = v_c.opponent_club_id;
  -- per answer: confident +1 morale / +0.15 control; calm +1 morale; provocative +1 morale and, against a human, -0.3
  -- to the opponent's control (unless they answered calmly, checked at match time); evasive nothing
  v_morale := least(3, (select count(*) from unnest(v_tones) t where t in ('confident','calm','provocative'))::int);
  v_own := 0.15 * (select count(*) from unnest(v_tones) t where t = 'confident');
  v_opp := case when coalesce(v_opp_human, false) then -0.3 * (select count(*) from unnest(v_tones) t where t = 'provocative') else 0 end;
  v_effects := jsonb_build_object('morale', v_morale, 'own_control', v_own, 'opp_control', v_opp,
                                  'calm', (select count(*) from unnest(v_tones) t where t = 'calm') > 0);
  if v_morale <> 0 then
    perform public._apply_effects(v_c.game_id, v_c.club_id, jsonb_build_array(jsonb_build_object('type','morale','scope','squad','delta', v_morale)), 'press:' || v_c.id);
  end if;
  update public.press_conferences set answers = p_answers, effects = v_effects, answered_at = now() where id = v_c.id;
  perform public._audit(v_c.game_id, auth.uid(), 'press.answer', 'press_conference', v_c.id::text, v_effects);
  return v_effects;
end $$;

-- ------------------------------------------------------------------ grants
revoke all on function public._apply_effects(uuid, uuid, jsonb, text) from public, anon, authenticated;
revoke all on function public.resolve_due_events(uuid, integer) from public, anon, authenticated;
grant execute on function public._apply_effects(uuid, uuid, jsonb, text), public.resolve_due_events(uuid, integer) to service_role;
do $$
declare f text;
begin
  foreach f in array array['save_training_plan(uuid, text, text)', 'save_match_plan(uuid, jsonb, jsonb)',
                           'answer_inbox_event(uuid, integer)', 'answer_press(uuid, jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
end $$;
